mapper.select:
select distinct d.dept_id, d.parent_id, d.ancestors, d.dept_name, d.order_num, d.province, d.city, d.area, d.dept_source, d.external_company_id, d.status, d.del_flag from sys_dept d inner join ( select device_dept.dept_id, device_dept.ancestors from sys_dept device_dept inner join ( select distinct dept_id from fe_sensor where dept_id is not null and (del_flag is null or del_flag = '0') union select distinct dept_id from fe_extinguisher where dept_id is not null and (del_flag is null or del_flag = '0') union select distinct dept_id from fe_fire_point where dept_id is not null and (del_flag is null or del_flag = '0') union select distinct dept_id from fe_gateway where dept_id is not null and (del_flag is null or del_flag = '0') union select distinct dept_id from fe_device_warning where dept_id is not null and (del_flag is null or del_flag = '0') ) used_dept on used_dept.dept_id = device_dept.dept_id where device_dept.del_flag = '0'
and device_dept.province = #{province}
and device_dept.city = #{city}
and device_dept.area = #{area}
) matched on d.dept_id = matched.dept_id or find_in_set(d.dept_id, matched.ancestors) where d.del_flag = '0' order by d.parent_id, d.order_num
